241	/// Allows to build tiny-skia paths from glyph outlines.
242	struct WrappedPathBuilder(sk::PathBuilder);
243	
244	impl OutlineBuilder for WrappedPathBuilder {
245	    fn move_to(&mut self, x: f32, y: f32) {
246	        self.0.move_to(x, y);
247	    }
248	
249	    fn line_to(&mut self, x: f32, y: f32) {
250	        self.0.line_to(x, y);
251	    }
252	
253	    fn quad_to(&mut self, x1: f32, y1: f32, x: f32, y: f32) {
254	        self.0.quad_to(x1, y1, x, y);
255	    }
256	
257	    fn curve_to(&mut self, x1: f32, y1: f32, x2: f32, y2: f32, x: f32, y: f32) {
258	        self.0.cubic_to(x1, y1, x2, y2, x, y);
259	    }
260	
261	    fn close(&mut self) {
262	        self.0.close();
263	    }
264	}
265	
266	// Alpha multiplication and blending are ported from:
267	// https://skia.googlesource.com/skia/+/refs/heads/main/include/core/SkColorPriv.h
268	
269	/// Blends two premulitplied, packed 32-bit RGBA colors. Alpha channel must be
270	/// in the 8 high bits.
271	fn blend_src_over(src: u32, dst: u32) -> u32 {
272	    src + alpha_mul(dst, 256 - (src >> 24))
273	}
274	
275	/// Alpha multiply a color.
276	fn alpha_mul(color: u32, scale: u32) -> u32 {
277	    let mask = 0xff00ff;
278	    let rb = ((color & mask) * scale) >> 8;
279	    let ag = ((color >> 8) & mask) * scale;
280	    (rb & mask) | (ag & !mask)
